INSERT INTO `areaclic` VALUES ('mdPerimetroCefalico','Permetro Ceflico','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deflang1046{\\fonttbl{\\f0\\fswiss\\fprq2\\fcharset0 Arial;}{\\f1\\fswiss\\fprq2 Arial;}{\\f2\\fswiss MS Sans Serif;}}\r\n\\viewkind4\\uc1\\pard\\b\\f0\\fs22 Per\\\'edmetro Cef\\\'e1lico (PC)\\f1 \r\n\\par \\b0 \r\n\\par \\f0 Verificar com fita m\\\'e9trica flex\\\'edvel e inel\\\'e1stica. Deve-se manter a cabe\\\'e7a fixa e medir a circunfer\\\'eancia m\\\'e1xima colocando a fita sobre a regi\\\'e3o frontal e na proemin\\\'eancia do occipital, contornando a cabe\\\'e7a, ao mesmo n\\\'edvel, \\\'e0 direita e a esquerda.\\f1 \r\n\\par \r\n\\par Fonte: JELLIFFE, D.B. - \\ul\\f0 Evaluaci\\\'f3n del estado de nutrici\\\'f3n de la comunidad.\\ulnone\\f1  Ginebra, OMS, 1968. Figura 1.\r\n\\par \\f2\\fs16 \r\n\\par }\r\n',9);
